val x = FloatArray(max); val y = FloatArray(max)
val vx = FloatArray(max); val vy = FloatArray(max)
var active = 0
fun step(dt: Float) {
    for (i in 0 until active) {        // counted loop over primitives, no boxing
        x[i] += vx[i] * dt
        y[i] += vy[i] * dt
    }
}
